#ifndef RINGBUF_H
#define RINGBUF_H

#include <stddef.h>
#include <stdint.h>

/* Fixed-capacity FIFO ring buffer of bytes. Not thread-safe. */
typedef struct ringbuf ringbuf_t;

/* Create a buffer holding up to `capacity` bytes (capacity > 0).
 * Returns NULL on invalid capacity or allocation failure. */
ringbuf_t *rb_create(size_t capacity);

/* Free the buffer. Accepts NULL. */
void rb_destroy(ringbuf_t *rb);

/* Append up to `len` bytes from `data`. Writes as many bytes as fit and
 * returns the number actually written (0 if full or arguments are NULL). */
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len);

/* Remove up to `len` bytes into `out`, oldest first. Returns the number
 * actually read (0 if empty or arguments are NULL). */
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len);

/* Copy up to `len` oldest bytes into `out` without removing them. */
size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len);

/* Number of bytes currently stored. */
size_t rb_size(const ringbuf_t *rb);

/* Total capacity given at creation. */
size_t rb_capacity(const ringbuf_t *rb);

/* Discard all content. */
void rb_clear(ringbuf_t *rb);

#endif

input.content:
#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;   /* write index */
    size_t tail;   /* read index */
    size_t count;  /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity) {
    if (capacity == 0)
        return NULL;
    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;
    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }
    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

static size_t ring_capacity(const ringbuf_t *rb) {
    return rb->capacity - 1;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data || len == 0)
        return 0;
    size_t cap = ring_capacity(rb);
    if (rb->count >= cap)
        return 0;
    size_t free_slots = cap - rb->count;
    size_t n = len < free_slots ? len : free_slots;
    /* Write may wrap around */
    size_t first = rb->capacity - rb->head; /* bytes from head to end */
    if (n <= first) {
        memcpy(rb->buf + rb->head, data, n);
    } else {
        memcpy(rb->buf + rb->head, data, first);
        memcpy(rb->buf, data + first, n - first);
    }
    rb->head = (rb->head + n) % rb->capacity;
    rb->count += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0)
        return 0;
    if (rb->count == 0)
        return 0;
    size_t n = len < rb->count ? len : rb->count;
    size_t first = rb->capacity - rb->tail;
    if (n <= first) {
        memcpy(out, rb->buf + rb->tail, n);
    } else {
        memcpy(out, rb->buf + rb->tail, first);
        memcpy(out + first, rb->buf, n - first);
    }
    rb->tail = (rb->tail + n) % rb->capacity;
    rb->count -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0)
        return 0;
    if (rb->count == 0)
        return 0;
    size_t n = len < rb->count ? len : rb->count;
    size_t first = rb->capacity - rb->tail;
    if (n <= first) {
        memcpy(out, rb->buf + rb->tail, n);
    } else {
        memcpy(out, rb->buf + rb->tail, first);
        memcpy(out + first, rb->buf, n - first);
    }
    return n;
}

size_t rb_size(const ringbuf_t *rb) {
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb) {
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb) {
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

#include "ringbuf.h"
#include <stdio.h>
#include <string.h>

static int ok = 1;
static void check(const char *desc, int condition) {
    if (!condition) {
        printf("FAIL: %s\n", desc);
        ok = 0;
    }
}

int main(void) {
    /* NULL / edge cases */
    check("rb_create(0) returns NULL", rb_create(0) == NULL);
    check("rb_destroy(NULL) no crash", 1);
    rb_destroy(NULL);

    /* basic create/destroy with size info */
    ringbuf_t *rb = rb_create(8);
    check("normal create succeeds", rb != NULL);
    check("capacity returns 8", rb_capacity(rb) == 8);
    check("empty size is 0", rb_size(rb) == 0);

    /* write and read - exact fit */
    uint8_t src[] = {1,2,3,4,5};
    size_t w = rb_write(rb, src, 5);
    check("wrote 5 bytes", w == 5);
    check("size after write is 5", rb_size(rb) == 5);

    uint8_t dst[16];
    size_t r = rb_read(rb, dst, 5);
    check("read 5 bytes", r == 5);
    check("data matches", memcmp(dst, src, 5) == 0);
    check("size after read is 0", rb_size(rb) == 0);

    /* wrap-around write */
    uint8_t buf[8];

    /* fill to capacity-1 (7 bytes used since one slot reserved) */
    for (int i = 0; i < 7; i++) {
        size_t s = rb->capacity - 1 - rb_size(rb);
        const uint8_t v = (uint8_t)(i + 1);
        if (s > 0) rb_write(rb, &v, 1);
    }
    check("filled ringbuf", rb_size(rb) == 7);

    /* read 4 from tail */
    memset(buf, 0, 8);
    rb_read(rb, buf, 4);

    /* write 6 more -> must wrap */
    for (int i = 0; i < 6; i++) {
        uint8_t v = (uint8_t)(i + 50);
        size_t s = rb_write(rb, &v, 1);
        check("wrap-write returned 1", s == 1);
    }

    /* ring should hold 7 total => we read 4 then wrote 6 = size 7 */
    check("size after wrap write is 7", rb_size(rb) == 7);

    /* read all and verify values: oldest first = {5,6,7} remaining + {0..5} written last 3+3 overlap */
    memset(buf, 0, 8);
    size_t total = rb_read(rb, buf, 7);
    check("read remaining 7 bytes", total == 7);

    /* verify wrap-around values - content depends on exact indexing */
    /* We have: after writing {1..7} then reading {1..4}, ring has {5,6,7} then wrote {50,51,52,53,54,55} */
    uint8_t expected[] = {7, 50, 51, 52, 53, 54, 55};
    check("wrap-around read matches", !memcmp(buf, expected, 7));

    /* peek doesn't remove data */
    rb_write(rb, &expected[0], 1);
    check("size after write is 1", rb_size(rb) == 1);
    size_t p = rb_peek(rb, buf, 1);
    check("peek returns 1", p == 1);
    check("peek value correct", buf[0] == 7);
    check("size unchanged after peek", rb_size(rb) == 1);

    /* clear */
    rb_clear(rb);
    check("size after clear is 0", rb_size(rb) == 0);

    /* write exceeding free space - should store what fits */
    uint8_t big[256];
    memset(big, 0xAA, sizeof(big));
    size_t partial = rb_write(rb, big, 256);
    check("partial write capped at capacity-1", partial == (rb_capacity(rb) - 1));

    /* NULL buffer operations */
    check("null rb_write returns 0", rb_write(NULL, src, sizeof(src)) == 0);
    check("null rb_read returns 0", rb_read(NULL, buf, sizeof(buf)) == 0);
    check("null rb_size returns 0", rb_size(NULL) == 0);
    check("clear with NULL no crash", 1);
    rb_clear(NULL);

    rb_destroy(rb);
    check("rb_create(NULL cap)", ok);
    printf("%s\n", ok ? "ALL TESTS PASSED" : "SOME TESTS FAILED");
    return ok ? 0 : 1;
}

