        uint8_t chunk[10];
        size_t written_so_far = 0;
        while (written_so_far < 63) {
            size_t need = 63 - written_so_far;
            size_t sneed = (need > sizeof(chunk)) ? sizeof(chunk) : need;
            memset(chunk, 0xBB, sneed);
            size_t n = rb_write(r, chunk, sneed);
            written_so_far += n;
        }
