    check("size==0 empty", rb_size(rb) == 0);

    /* ---- write/read in a loop, testing wrap-around ---- */
    {
        ringbuf_t *r = rb_create(4); /* 3 usable slots */
        uint8_t out[4] = {0};
        for (int i = 0; i < 20; i++) {
            uint8_t v = (uint8_t)(i + 1);
            size_t w = rb_write(r, &v, 1); (void)w;
            memset(out, 0, sizeof(out));
