        ringbuf_t *r = rb_create(16); /* 15 usable slots */
        uint8_t out[16];
        /* Fill all 15 slots with bytes 0xFF, 0xFE, ... */
        for (int i = 0; i < 15; i++) {
            uint8_t v = (uint8_t)(0xFF - i);
            size_t w = rb_write(r, &v, 1); (void)w;
        }
        check("full size==15", rb_size(r) == 15);

        /* Discard first 3 bytes of fill data */
        uint8_t discard[4] = {0};
        rb_read(r, discard, 3);
        check("size after reading 3 is 12", rb_size(r) == 12);

        /* Now write 6 more bytes to push wrap-around. We have capacity-15-slots... wait: */
        /* ringbuf has 15 usable slots, head/tail positions mean we can't use all of them */

        /* Let me just do a controlled test: create 4-slot buf (3 usable) */
    }

    /* ---- wrap in small buf: fill 2, drain 1, fill 3 more to wrap ---- */
    {
        ringbuf_t *r = rb_create(4); /* 3 usable slots */
        uint8_t out[4] = {0};

        /* Write 2 bytes at slot indices 0,1 -> tail=0, head=2 */
        uint8_t v1 = 10;
        rb_write(r, &v1, 1);
        check("size==1", rb_size(r) == 1);
        uint8_t v2 = 20;
        rb_write(r, &v2, 1);
        check("size==2", rb_size(r) == 2);

        /* Read 1 byte: tail=0 -> now tail=head means empty... */
        memset(out, 0, sizeof(out));
        rb_read(r, out, 1);
        check("(drained one) out[0]==10", out[0] == 10);
